@dataclass(order=False)  # Disable auto-generated comparison; we define custom __lt__
class Task:
    """Represents a task to be distributed. Uses heapq for priority ordering.
    
    Performance note: __lt__ is inverted for heapq min-heap behavior.
    Higher priority value = more urgent, but heapq pops smallest first.
    We compare in reverse: self.priority > other.priority means self is more urgent.
    """
    task_id: str
    task_type: str  # "llm", "file_io", "computation", "analysis"
    complexity: TaskComplexity
    payload: Any
    callback: Optional[Callable] = None
    priority: int = 0  # Higher = more urgent
    created_at: datetime = field(default_factory=datetime.now)
    started_at: Optional[datetime] = None
    completed_at: Optional[datetime] = None
    result: Any = None
    error: Optional[str] = None
    gpu_model: Optional[str] = None

    def __lt__(self, other: 'Task') -> bool:
        """Comparison for heapq: higher priority = more urgent = popped first.
        
        heapq is a min-heap, so we invert: priority 0 (highest urgency)
        should be popped first. We use negative priority internally.
        """
        if not isinstance(other, Task):
            return NotImplemented
        # Higher priority value = more urgent, but heapq pops smallest first
        # So we compare in reverse: self.priority > other.priority means self is more urgent
        return self.priority > other.priority
    
    def __eq__(self, other: object) -> bool:
        """Equality based on task_id for set operations and duplicate detection."""
        if not isinstance(other, Task):
            return NotImplemented
        return self.task_id == other.task_id
    
    def __hash__(self) -> int:
        """Hash based on task_id for O(1) set membership."""
        return hash(self.task_id)


class PriorityTaskQueue:
    """Thread-safe priority queue using heapq for O(log n) operations.
    
    Replaces the previous deque-based implementation which required O(n) scans
    for priority resolution. This implementation provides:
    - O(log n) push/pop operations
    - O(1) peek operation
    - O(1) duplicate detection via set
    - Thread-safe async operations with asyncio.Lock
    """
    
    def __init__(self):
        self._heap: list[Task] = []
        self._lock = asyncio.Lock()
        self._task_ids: set[str] = set()  # For O(1) duplicate detection
    
    async def push(self, task: Task) -> None:
        """Push a task onto the priority queue. O(log n)."""
        async with self._lock:
            if task.task_id in self._task_ids:
                logger.warning(f"Duplicate task ID detected: {task.task_id}")
                return
            heapq.heappush(self._heap, task)
            self._task_ids.add(task.task_id)
            logger.debug(f"Task {task.task_id} pushed. Queue size: {len(self._heap)}")
    
    async def pop(self) -> Optional[Task]:
        """Pop the highest-priority task. O(log n)."""
        async with self._lock:
            if not self._heap:
                return None
            task = heapq.heappop(self._heap)
            self._task_ids.discard(task.task_id)
            logger.debug(f"Task {task.task_id} popped. Queue size: {len(self._heap)}")
            return task
    
    async def peek(self) -> Optional[Task]:
        """View the highest-priority task without removing it. O(1)."""
        async with self._lock:
            return self._heap[0] if self._heap else None
    
    async def remove(self, task_id: str) -> Optional[Task]:
        """Remove a specific task by ID. O(n) worst-case, but rare operation.
        
        Uses swap-with-last pattern to avoid O(n) shift cost.
        """
        async with self._lock:
            for i, task in enumerate(self._heap):
                if task.task_id == task_id:
                    # Swap with last element and pop (O(1) removal)
                    self._heap[i] = self._heap[-1]
                    self._heap.pop()
                    heapq.heapify(self._heap)  # Restore heap invariant O(n)
                    self._task_ids.discard(task_id)
                    logger.info(f"Task {task_id} removed from queue")
                    return task
            logger.warning(f"Task {task_id} not found in queue")
            return None
    
    async def size(self) -> int:
        """Return the number of tasks in the queue. O(1)."""
        async with self._lock:
            return len(self._heap)
    
    async def clear(self) -> None:
        """Clear all tasks. O(1)."""
        async with self._lock:
            self._heap.clear()
            self._task_ids.clear()
            logger.info("Task queue cleared")
    
    async def get_all_tasks(self) -> List[Task]:
        """Return a copy of all tasks in the queue. O(n)."""
        async with self._lock:
            return list(self._heap)


